  "description": "OpenCode v2 plugin that sends Slack and Discord notifications when sessions complete, error, need permission, or ask a question.",
  "type": "module",
  "license": "MIT",
  "author": "asliutkarsh",
  "homepage": "https://github.com/asliutkarsh/opencode2-notifier",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/asliutkarsh/opencode2-notifier.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notifier",
    "slack",
    "discord",
    "notifications"
  ],
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": "2.0.18"
  },
  "devDependencies": {
    "typescript": "^5.9.2",
    "@types/bun": "latest"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  }
